struct BuiltinTileEntry
{
    const char *key;
    const uint8_t *data;
    size_t len;
};

static const BuiltinTileEntry kBuiltinTiles[] = {
    {"_BIZJET", kTile_BIZJET, sizeof(kTile_BIZJET)},
    {"_CARGO", kTile_CARGO, sizeof(kTile_CARGO)},
    {"_CESSNA", kTile_CESSNA, sizeof(kTile_CESSNA)},
    {"_HELI", kTile_HELI, sizeof(kTile_HELI)},
    {"_LIGHT", kTile_LIGHT, sizeof(kTile_LIGHT)},
    {"_PRIVATE", kTile_PRIVATE, sizeof(kTile_PRIVATE)},
};

const uint8_t *builtinTile(const char *key, size_t &len)
{
    for (const BuiltinTileEntry &t : kBuiltinTiles)
        if (key && strcmp(key, t.key) == 0)
        {
            len = t.len;
            return t.data;
        }
    len = 0;
    return nullptr;
}

size_t builtinTileCount() { return sizeof(kBuiltinTiles) / sizeof(kBuiltinTiles[0]); }

const char *builtinTileKey(size_t i)
{
    return i < builtinTileCount() ? kBuiltinTiles[i].key : nullptr;
}
